// Compares a student's phonetic transcription against the expected phonetic
// generated by hebrewRules.js, and produces per-word and per-syllable scoring.

import { tokenizeWord, getExpectedPhonetic } from './hebrewRules.js'
import { syllableRight, wordScoreOf } from './wordScore.js'
import {
  describe, describeHeardVowel, latinToSay, consonantSay, vowelSay,
  vowelSignName, letterLabel, soundOfOtherLetter,
} from './soundGuide.js'

// For a given syllable, compute all acceptable Latin renderings of its vowel.
// The set depends on the Hebrew vowel sign (not on tradition) — different
// transliteration conventions render the same vowel differently. Variants that
// end in a letter which could start the next syllable ("oh", "uh") are safe
// because the aligner prefers the shortest variant that leaves the next
// syllable able to start.
function vowelVariants(seg) {
  const base = seg.vowel ?? ''
  if (!base) return ['']
  const vowel = seg.atom?.vowel
  // Last sounded syllable: the word's final letter, or the letter before a
  // silent final ה/א (תּוֹרָה "torah", פֶּה "peh" — the trailing h is spelling)
  const next = seg.nextAtom
  const silentNext = next?.isFinal && !next.vowel &&
    (next.letter === 'א' || (next.letter === 'ה' && !next.dagesh))
  const isFinal = !!seg.atom?.isFinal || silentNext
  // altVowels: readings the rules engine accepts leniently (qamats katan read
  // as gadol, a sheva that may be silent). '' means "no vowel" is fine.
  const out = new Set([base, ...(seg.altVowels ?? [])])

  if (vowel === 'tzere') {
    // tzere written as "e", "ei", "ey", "ay", "ai"
    for (const v of ['ei', 'ey', 'ay', 'ai']) out.add(v)
  } else if (vowel === 'holam') {
    // "oy"/"oi" (Ashkenazic), "oh"/"ow" (American spelling: "shalohm")
    for (const v of ['oy', 'oi', 'oh', 'ow']) out.add(v)
  } else if (vowel === 'qamats') {
    if (isFinal && out.has('a')) out.add('ah') // "+ah" trailing only at word end
    if (out.has('o')) { out.add('aw'); out.add('oh') } // Ashkenazic kamatz / qamats katan
    if (out.has('u')) out.add('uh') // Ashkenazic kamatz reduced to "buh-"

  } else if (vowel === 'patah') {
    if (isFinal) out.add('ah') // "+ah" trailing only at word end
  } else if (vowel === 'segol') {
    if (isFinal) out.add('eh') // "+eh" trailing only at word end
    // Segol before a silent yud (אַחֶיךָ): "acheycha" is a common reading too
    if (seg.atom?.yudAfter) for (const v of ['ey', 'ei']) out.add(v)
  } else if (vowel === 'hiriq') {
    out.add('ee') // English spelling of "i" ("anee", "bereesheet")
    if (isFinal) out.add('iy')
  } else if (vowel === 'shuruk' || vowel === 'qubuts') {
    out.add('oo')
  } else if (vowel === 'sheva') {
    // Sheva na is a schwa — heard as "e", "eh", "u" or "uh"
    for (const v of ['eh', 'u', 'uh']) out.add(v)
    // Before yud it colors toward "i" (בְּיוֹם "biyom")
    if (seg.nextAtom?.letter === 'י') out.add('i')
  }
  return [...out]
}

// Group expected segments into syllables: each syllable is one consonant + its
// vowel atom. We keep the original Hebrew chars per syllable for display.
function buildSyllables(atoms, segments) {
  return segments
    .filter(seg => seg.sound || seg.consonant || seg.vowel || seg.atom.letter)
    .map(seg => {
      const a = seg.atom
      // Reconstruct the display form: letter + nikud marks
      let display = a.letter
      const VOWEL_GLYPH = {
        'sheva':'ְ', 'hataf-segol':'ֱ', 'hataf-patah':'ֲ', 'hataf-qamats':'ֳ',
        'hiriq':'ִ', 'tzere':'ֵ', 'segol':'ֶ', 'patah':'ַ', 'qamats':'ָ',
        'holam':'ֹ', 'shuruk':'ּ', 'qubuts':'ֻ',
      }
      if (a.dagesh && a.letter !== 'ה') display += 'ּ' // dagesh
      if (a.letter === 'ה' && a.dagesh) display += 'ּ' // mappiq
      if (a.shinDot) display += 'ׁ'
      if (a.sinDot)  display += 'ׂ'
      if (a.vowel && VOWEL_GLYPH[a.vowel] && a.vowel !== 'shuruk') display += VOWEL_GLYPH[a.vowel]
      const nextAtom = a.isFinal ? null : atoms[seg.atomIndex + 1]
      const vVariants = vowelVariants({ ...seg, nextAtom })
      const c = seg.consonant ?? ''
      const consonants = [c, ...(seg.altConsonants ?? [])]
      return {
        atomIndex: seg.atomIndex,
        atom: a,
        display,
        expected: seg.sound,
        consonant: seg.consonant,
        altConsonants: seg.altConsonants ?? [],
        vowel: seg.vowel,
        shevaType: seg.shevaType,
        qamatsType: seg.qamatsType,
        patachGenuvah: !!seg.patachGenuvah,
        vowelVariants: vVariants,
        variants: consonants.flatMap(k => vVariants.map(v => seg.patachGenuvah ? v + k : k + v)),
      }
    })
}

// Normalize student phonetic for matching. Folds common transliteration variants
// to the canonical form used by getExpectedPhonetic so the alignment doesn't
// false-flag innocent spelling differences.
//   tz, ts, tzh  → ts   (צ tsadi)
//   kh, x        → ch   (ח/כ guttural)
//   q            → k    (ק)
//   j            → y    (German/academic "Jisrael" — Hebrew has no "j" sound)
//   w + vowel    → v    (academic "wayomer" for vav)
// Apostrophes for alef/ayin ("'esav") are dropped with the other punctuation.
export function normalizeStudent(phonetic) {
  return (phonetic ?? '')
    .toLowerCase()
    .replace(/[^a-z\s]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/tzh/g, 'ts')
    .replace(/tz/g, 'ts')
    .replace(/kh/g, 'ch')
    .replace(/\bx/g, 'ch')
    .replace(/q/g, 'k')
    .replace(/j/g, 'y')
    .replace(/w(?=[aeiou])/g, 'v')
    .trim()
}

// Greedy left-to-right alignment of expected sounds against student transcription.
// For each syllable, try to match its expected sound at the current student
// pointer. Allows small look-ahead skips (up to MAX_SKIP) to handle inserted
// sounds, but doesn't try to globally optimize.
const MAX_SKIP = 3

// Identify the phonological consonant unit at the start of `remaining`. Digraphs
// like "sh", "ch", "ts", "tz", "kh" count as a single unit. Single consonant
// chars otherwise. Returns "" if remaining starts with a vowel.
// Note: "th" deliberately NOT a digraph — in Hebrew transliteration the "t"
// and following "h" are almost always two separate sounds (e.g. ת ending
// one syllable, ה starting the next, as in "veethanefesh").
const DIGRAPHS = ['sh', 'ch', 'ts', 'tz', 'kh']
function identifyConsonantUnit(remaining) {
  if (!remaining) return ''
  const two = remaining.slice(0, 2).toLowerCase()
  if (DIGRAPHS.includes(two)) return two
  const one = remaining[0]
  if (one && /[^aeiouy]/.test(one)) return one
  return ''
}

// Check if `expected` matches the start of `remaining` cleanly, without being
// part of a longer digraph. For example "s" should NOT match the start of "sh"
// because the "sh" is a single phonetic unit (shin sound). Same for "t" inside
// "ts"/"tz"/"th", "c" inside "ch", "k" inside "kh".
function cleanMatch(remaining, expected) {
  if (!remaining.startsWith(expected)) return false
  const after = remaining[expected.length] ?? ''
  const lastChar = expected[expected.length - 1]
  if (lastChar === 's' && after === 'h') return false  // would be "sh"
  if (lastChar === 't' && (after === 's' || after === 'z')) return false  // ts/tz digraphs (but NOT th)
  if (lastChar === 'c' && after === 'h') return false
  if (lastChar === 'k' && after === 'h') return false
  return true
}

// Acceptable phonetic variants. Each expected sound may be transliterated
// multiple ways; we accept any of them as a clean match. Apply ONLY for
// boundary-sensitive sounds (diphthong endings, standalone y/i).
const SOUND_VARIANTS = {
  'y':  ['y', 'i'],   // word-final yod (chai/chay)
  'ay': ['ay', 'ai'],
  'oy': ['oy', 'oi'],
  'ey': ['ey', 'ei'],
}

// Try each acceptable variant of an expected sound against the start of `remaining`.
// Returns the variant string that matched, or null.
function matchAnyVariant(remaining, expected) {
  const variants = SOUND_VARIANTS[expected] ?? [expected]
  for (const v of variants) {
    if (cleanMatch(remaining, v)) return v
  }
  return null
}

// Pick which of a syllable's accepted variants the student said at the start of
// `remaining`: the SHORTEST one whose tail leaves the next syllable able to
// start, else the LONGEST that matches at all. This stops a longer variant
// from eating chars that belong to the next syllable. Example: רֹעִי "roi" —
// use "ro" for cholam (not "roi"), so the chirik syllable can claim its "i".
// With no audible syllable left, prefer the variant that ends the word ("aniy").
// When the next syllable is misread anyway, the whole vowel is this one's:
// Ashkenazic בֵּית read "beit" is "bei" + a wrong "t", not "be" + a stray "i".
function pickVariant(remaining, variants, nextSyl) {
  let longest = null
  for (const v of variants.slice().sort((a, b) => a.length - b.length)) {
    if (!v || !cleanMatch(remaining, v)) continue
    longest = v
    const tail = remaining.slice(v.length)
    if (nextSyl ? nextSyllableCanStartAt(tail, nextSyl) : tail === '') return v
  }
  return longest
}

// Same disambiguation but for indexOf (look-ahead matching)
function cleanIndexOf(haystack, needle) {
  let from = 0
  while (from <= haystack.length - needle.length) {
    const idx = haystack.indexOf(needle, from)
    if (idx === -1) return -1
    const after = haystack[idx + needle.length] ?? ''
    const last = needle[needle.length - 1]
    const isDigraph =
      (last === 's' && after === 'h') ||
      (last === 't' && (after === 's' || after === 'z')) ||  // ts/tz only, NOT th
      (last === 'c' && after === 'h') ||
      (last === 'k' && after === 'h')
    if (!isDigraph) return idx
    from = idx + 1
  }
  return -1
}

function nextSyllableCanStartAt(remaining, nextSyl) {
  if (!nextSyl) return true              // no next syllable — anything works
  if (!nextSyl.expected) return true     // next syllable is silent — anything works
  // Try any of next syllable's accepted variants
  for (const v of nextSyl.variants ?? [nextSyl.expected]) {
    if (cleanMatch(remaining, v)) return true
  }
  // Or at least its consonant
  if (nextSyl.consonant && cleanMatch(remaining, nextSyl.consonant)) return true
  return false
}

// Could the next audible syllable begin with `ch`, in any accepted spelling?
// Used to keep vowel-elongation detection from eating the next syllable's
// vowel (Ashkenazic הָאָרֶץ "haarets": the second "a" is the alef's kamatz).
function nextSyllableStartsWith(nextSyl, ch) {
  if (!nextSyl?.expected) return false
  return (nextSyl.variants ?? [nextSyl.expected]).some(v => v[0] === ch)
}

function alignSyllables(syllables, studentPhonetic) {
  const student = normalizeStudent(studentPhonetic).replace(/\s+/g, '')
  let pos = 0
  const matches = []

  for (let i = 0; i < syllables.length; i++) {
    const syl = syllables[i]
    const expected = syl.expected

    if (!expected) {
      matches.push({ ...syl, status: 'silent', heardAt: pos, heard: '' })
      continue
    }

    // Look ahead to the next AUDIBLE syllable, skipping silent ones (alef/ayin,
    // final silent ה). A silent next syllable would pass any alignment check
    // vacuously, so we need to peek further.
    let nextSyl = null
    for (let j = i + 1; j < syllables.length; j++) {
      if (syllables[j].expected) { nextSyl = syllables[j]; break }
    }

    // Gemination: a doubled consonant ("vayyomer" for וַיֹּאמֶר, "chonneni" for
    // חָנֵּנִי — dagesh chazak) sounds the same as a single one. Skip the extra
    // copy when the syllable then matches cleanly; otherwise the second copy
    // may belong to the next syllable (הִנְנִי read "hinni" is a real error).
    const c0 = student[pos]
    if (syl.consonant?.length === 1 && c0 === syl.consonant && student[pos + 1] === c0) {
      const rest = student.slice(pos + 1)
      const v = pickVariant(rest, syl.variants ?? [expected], nextSyl)
      const tail = v != null && rest.slice(v.length)
      if (v && (nextSyl ? nextSyllableCanStartAt(tail, nextSyl) : tail === '')) pos++
    }

    const remaining = student.slice(pos)

    let variantMatch = pickVariant(remaining, syl.variants ?? [expected], nextSyl)
    if (!variantMatch) variantMatch = matchAnyVariant(remaining, expected)
    if (variantMatch) {
      // Check for vowel-elongation right after the matched syllable, but ONLY
      // if the repeated vowel char wouldn't be the legitimate start of the next
      // audible syllable. Otherwise we'd eat the next syl's vowel (e.g. "veet"
      // for וְאֵת: the second "e" belongs to alef+segol, not to elongation).
      let elongated = ''
      const lastVowelChar = variantMatch.match(/[aeiouy]$/)?.[0]
      const nextStartsWithSameVowel = lastVowelChar && nextSyllableStartsWith(nextSyl, lastVowelChar)
      if (lastVowelChar && !nextStartsWithSameVowel) {
        const after = remaining.slice(variantMatch.length)
        while (elongated.length < 3 && after[elongated.length] === lastVowelChar) {
          elongated += lastVowelChar
        }
      }
      // A sheva nach said aloud ("yiserael" for יִשְׂרָאֵל): the extra vowel
      // belongs to this letter, not to the next one. Only when the next
      // syllable can't start with that vowel itself (an alef's vowel).
      if (syl.shevaType === 'nach') {
        const after = remaining.slice(variantMatch.length)
        const extra = after.match(/^[aeiou]+/)?.[0]
        const rest = extra && after.slice(extra.length)
        const voiced = extra && (nextSyl
          ? !nextSyllableCanStartAt(after, nextSyl) && nextSyllableCanStartAt(rest, nextSyl)
          : rest === '')
        if (voiced) {
          matches.push({
            ...syl,
            status: 'extra-vowel',
            heardAt: pos,
            heard: variantMatch + extra,
            heardConsonant: variantMatch,
            heardVowel: extra,
            consonantMatched: true,
            vowelMatched: false,
          })
          pos += variantMatch.length + extra.length
          continue
        }
      }
      const status = elongated ? 'vowel-elongated' : 'matched'
      matches.push({
        ...syl,
        status,
        heardAt: pos,
        heard: variantMatch + elongated,
        vowelElongated: elongated,
        consonantMatched: true,
        vowelMatched: true,
      })
      pos += variantMatch.length + elongated.length
      continue
    }

    if (syl.patachGenuvah) {
      const g = alignPatachGenuvah(syl, remaining)
      if (g) {
        const { consumed, ...rest } = g
        matches.push({ ...syl, ...rest, heardAt: pos })
        pos += Math.max(1, consumed)
        continue
      }
    }

    // Phase-by-phase matching: try consonant separately, then vowel separately.
    // This handles silent-consonant syllables (alef, ayin, final silent ה) and
    // prevents over-grabbing vowels that belong to the next syllable.
    let consumed = 0
    let heardConsonant = ''
    let heardVowel = ''
    let insertedBefore = '' // characters student inserted before the matched consonant
    let consonantMatched = !syl.consonant
    let vowelMatched = !syl.vowel

    // -- Consonant phase --
    if (syl.consonant) {
      const consonantOptions = [syl.consonant, ...(syl.altConsonants ?? [])]
      let cMatch = null
      for (const k of consonantOptions) { cMatch = matchAnyVariant(remaining, k); if (cMatch) break }

      // Soft-match fallback: cleanMatch refuses to match "t" when followed by
      // "s"/"z" (would form ts/tz digraph), and similarly for sh/ch/kh. But if
      // the next audible syllable's consonant starts with the digraph-completing
      // char, then the "extra" char rightfully belongs to that next syllable and
      // the digraph block is wrong here.
      // e.g. אֶת־שָׂרַי → "etsaray": the "ts" is really ת + שׂ, not צ.
      if (!cMatch && remaining.startsWith(syl.consonant)) {
        const afterChar = remaining[syl.consonant.length] ?? ''
        const lastC = syl.consonant[syl.consonant.length - 1]
        const wouldFormDigraph =
          (lastC === 't' && (afterChar === 's' || afterChar === 'z')) ||
          (lastC === 's' && afterChar === 'h') ||
          (lastC === 'c' && afterChar === 'h') ||
          (lastC === 'k' && afterChar === 'h')
        const nextC = nextSyl?.consonant?.[0]
        if (wouldFormDigraph && nextC === afterChar) {
          cMatch = syl.consonant
        }
      }

      if (cMatch) {
        heardConsonant = cMatch
        consumed += cMatch.length
        consonantMatched = true
      } else {
        // Lookahead: maybe the student inserted 1-2 consonants before the
        // expected consonant. If so, treat those as inserted-before chars and
        // still credit the syllable's consonant as matched.
        // Never start inside a digraph: the "h" of "sh" isn't an "h" ("kashem").
        let skip = 0, laterMatch = null
        for (let k = 1; k <= 4 && k < remaining.length; k++) {
          if (DIGRAPHS.includes(remaining.slice(k - 1, k + 1))) continue
          const m = consonantOptions.map(opt => matchAnyVariant(remaining.slice(k), opt)).find(Boolean)
          if (m) { skip = k; laterMatch = m; break }
        }
        if (laterMatch) {
          insertedBefore = remaining.slice(0, skip)
          heardConsonant = laterMatch
          consumed += skip + laterMatch.length
          consonantMatched = true
        } else if (remaining[0] === 'y' && /[aeiou]/.test(remaining[1] ?? '') &&
                   !(nextSyl && nextSyllableCanStartAt(remaining, nextSyl))) {
          // "y" before a vowel is a consonant, not a vowel (unless it's the
          // next letter's: "veyeh" for וֶהְיֵה). Right after an "i" it's the
          // glide into the next vowel: "aviyo" for אָבִיךָ is "avi-o", with the
          // "kh" left out. Otherwise this letter was said as "y".
          if (student[pos - 1] !== 'i') heardConsonant = 'y'
          consumed += 1
        } else {
          // True mismatch — capture the digraph-aware consonant unit for reporting
          heardConsonant = identifyConsonantUnit(remaining)
          consumed += heardConsonant.length
        }
      }
    } else if (syl.vowel) {
      // No consonant expected (alef/ayin/silent final ה) but a vowel is.
      // Skim past any extra consonant the student inserted before the vowel.
      const vowelMatch = remaining.slice(0, 4).match(/[aeiouy]/)
      if (vowelMatch && vowelMatch.index > 0) {
        insertedBefore = remaining.slice(0, vowelMatch.index)
        consumed += vowelMatch.index
        consonantMatched = false // student inserted an unwanted consonant
      }
    }

    // -- Vowel phase --
    let vowelElongated = ''
    if (syl.vowel) {
      const afterConsonant = remaining.slice(consumed)
      const vMatch = pickVariant(afterConsonant, syl.vowelVariants ?? [syl.vowel], nextSyl)
      if (!vMatch && syl.vowelVariants?.includes('')) {
        vowelMatched = true // vowel is optional here (sheva that may be silent)
      } else if (vMatch) {
        heardVowel = vMatch
        consumed += vMatch.length
        vowelMatched = true

        // Vowel-elongation: student held the vowel longer than written. Only
        // detect when the repeated char wouldn't legitimately belong to the
        // next audible syllable's vowel.
        const after = remaining.slice(consumed)
        const lastVowelChar = vMatch[vMatch.length - 1]
        const nextStartsWithSameVowel = nextSyllableStartsWith(nextSyl, lastVowelChar)
        if (/[aeiouy]/.test(lastVowelChar) && !nextStartsWithSameVowel) {
          let extra = 0
          while (extra < 3 && after[extra] === lastVowelChar) extra++
          if (extra > 0) {
            vowelElongated = after.slice(0, extra)
            consumed += extra
          }
        }
      } else {
        // Vowel didn't match. Don't grab a vowel char that belongs to the
        // next audible syllable's expected sound (e.g. the "u" in "tsu" is
        // really for א+shuruk in וַיֵּצְאוּ — leave it for the next syllable).
        const expectedVowelLen = syl.vowel.length
        const vowelChars = afterConsonant.match(/^[aeiouy]+/)?.[0] ?? ''
        const wouldGrab = vowelChars.slice(0, expectedVowelLen)
        const nextStartsWithThis =
          wouldGrab && nextSyl?.expected && nextSyl.expected[0] === wouldGrab[0]
        if (!nextStartsWithThis) {
          heardVowel = wouldGrab
          consumed += heardVowel.length
        }
      }
    }

    // Decide status from the phase results
    let status
    if (consonantMatched && vowelMatched) {
      if (insertedBefore) status = 'matched-with-insertion'
      else if (vowelElongated) status = 'vowel-elongated'
      else status = 'matched'
    } else if (consonantMatched && !vowelMatched) {
      status = syl.vowel ? 'vowel-mismatch' : (heardVowel ? 'extra-vowel' : 'matched')
    } else if (!consonantMatched && vowelMatched && !syl.consonant) {
      // Silent expected consonant but student inserted one before the vowel
      status = 'extra-consonant'
    } else {
      status = 'mismatch'
    }

    // Skipped syllable: when this syllable didn't match, the reader may have
    // left it out ("ve'escha" for וְאֶעֶשְׂךָ drops one "e"). Reading it as a
    // wrong sound would consume the next syllable's sounds and throw every
    // later syllable out of step, so one slip showed up as three mistakes.
    // Call it skipped when what was said here is exactly the next syllable
    // and the wrong-sound reading would leave the next one misread too
    // ("mimoladekh" for וּמִמּוֹלַדְתְּךָ is a skipped וּ, not וּ said "mi" and מִ
    // skipped); a plain wrong letter ("rereshit") keeps the next in step.
    const isProblem = status !== 'matched' && status !== 'vowel-elongated'
    if (isProblem && nextSyl) {
      const nextVariants = nextSyl.variants ?? [nextSyl.expected]
      const afterWrong = remaining.slice(Math.max(1, consumed))
      const wrongSoundFits = nextVariants.some(v => v && cleanMatch(afterWrong, v))
      const skipFits = nextVariants.some(v => v && cleanMatch(remaining, v))
      if (!wrongSoundFits && skipFits) {
        matches.push({
          ...syl,
          status: 'missing',
          heardAt: pos,
          heard: '',
          heardConsonant: '',
          heardVowel: '',
          consonantMatched: !syl.consonant,
          vowelMatched: !syl.vowel,
        })
        continue // nothing consumed: the next syllable starts here
      }
    }

    matches.push({
      ...syl,
      status,
      heardAt: pos,
      heard: insertedBefore + heardConsonant + heardVowel + vowelElongated,
      heardConsonant,
      heardVowel,
      insertedBefore,
      vowelElongated,
      consonantMatched,
      vowelMatched,
    })
    pos += Math.max(1, consumed)
  }

  // Track if the student transcription has trailing chars not consumed (might
  // be a sheva nach inserted or extra sound at end)
  const trailing = student.slice(pos)
  return { matches, trailing }
}

// Patach genuvah syllables are vowel-then-consonant ("ach"), so the regular
// consonant-then-vowel phases don't fit. Called only after the accepted
// variants failed. Returns null to fall back to the generic phases.
function alignPatachGenuvah(syl, remaining) {
  const c = syl.consonant
  // Most common error: reading the patach after the letter ("rucha")
  if (c && cleanMatch(remaining, c + 'a')) {
    return {
      status: 'genuvah-reversed', heard: c + 'a', heardConsonant: c, heardVowel: 'a',
      consonantMatched: true, vowelMatched: false, consumed: c.length + 1,
    }
  }
  const heardVowel = remaining.match(/^[aeiouy]*/)[0]
  const afterVowel = remaining.slice(heardVowel.length)
  if (c && !cleanMatch(afterVowel, c)) return null
  return {
    status: 'vowel-mismatch', heard: heardVowel + (c ?? ''), heardConsonant: c, heardVowel,
    consonantMatched: true, vowelMatched: false, consumed: heardVowel.length + (c?.length ?? 0),
  }
}

// What to tell the student about a syllable, from its match status: its
// problems, each { kind, count, text } — the kind of mistake (ISSUE_LABELS in
// wordScore.js), how many mistakes it is (a skipped syllable is one per sound
// it has), and what to say about it — and the note, all their texts together
// ('' when it was read right). Notes spell every sound with the sound key
// (soundGuide.js): "ee" as in "see", not "i".
const RIGHT = { note: '', problems: [] }
const issue = (kind, note) => ({ note, problems: [{ kind, count: 1, text: note }] })
// A vowel note's kind: a vowel said differently, or one left out
const vowelIssue = heardVowel => (heardVowel ? 'wrong-vowel' : 'missing-sound')

function syllableNote(m, tradition, shevaMode) {
  // Silent atoms (e.g. final silent ה) are always right
  if (m.status === 'silent') return RIGHT

  // A correctly read sound is fully correct: the rules decide right or wrong
  if (m.status === 'matched') return RIGHT

  if (m.status === 'matched-with-insertion') {
    return issue('extra-sound', `Extra "${latinToSay(m.insertedBefore)}" sound before ${m.atom.letter} — it shouldn't be there.`)
  }

  if (m.status === 'vowel-elongated') {
    return issue('held-vowel', `Held the vowel too long — it's a short ${describe(vowelSay(m, tradition) ?? latinToSay(m.vowel))}.`)
  }

  if (m.status === 'extra-vowel') {
    // Probably a sheva nach that was pronounced as vocal
    if (m.shevaType === 'nach' && shevaMode === 'enforce') {
      return issue('extra-sound', `Sheva nach is silent — no vowel after this letter. You said ${describeHeardVowel(m.heardVowel)}.`)
    }
    return RIGHT // benign extra vowel: not a mistake
  }

  if (m.status === 'missing') return skippedNote(m, tradition)

  if (m.status === 'genuvah-reversed') {
    return issue('wrong-vowel', `Patach genuvah — the "ah" is said before the final ${m.atom.letter}, not after it. You said "${latinToSay(m.heard)}".`)
  }

  if (m.status === 'vowel-mismatch') {
    // Consonant right, vowel different
    if (m.patachGenuvah) {
      return issue(vowelIssue(m.heardVowel), `Patach genuvah — a short "ah" is said before the final ${m.atom.letter}` +
        (m.heardVowel ? ` — you said ${describeHeardVowel(m.heardVowel)}.` : ' — it was left out.'))
    }
    if (m.shevaType === 'na' && shevaMode === 'enforce' && !m.heardVowel) {
      return issue('missing-sound', `Sheva na is ${describe('uh')} — it was left out, so the letters ran together.`)
    }
    if (m.shevaType === 'na' && shevaMode === 'enforce') {
      return issue('wrong-vowel', `Sheva na is ${describe('uh')} — you said ${describeHeardVowel(m.heardVowel)}.`)
    }
    return issue(vowelIssue(m.heardVowel), vowelNote(m, tradition))
  }

  if (m.status === 'extra-consonant') {
    const L = m.atom.letter
    const extra = latinToSay(m.insertedBefore)
    // A silent letter carrying a vowel (אֶ, אָ, עַ) is read as just that vowel.
    // Calling the letter "silent" here reads as "say nothing", so name the vowel.
    if (m.vowel) {
      const where = m.atom.wordStart ? `at the start — ${m.display}` : `before ${m.display} — it`
      return issue('extra-sound', `Extra "${extra}" sound ${where} is just the vowel ${describe(vowelSay(m, tradition))}, with no consonant before it.`)
    }
    const which = L === 'ה' ? 'silent ה' : L === 'א' ? 'silent א (alef)' : L === 'ע' ? 'silent ע (ayin)' : L
    return issue('extra-sound', `Extra "${extra}" sound before ${which} — that letter is silent here.`)
  }

  if (m.status === 'mismatch') return buildMismatchNote(m, tradition)

  return RIGHT
}

// A syllable left out: one missing sound for each sound it has, as the score
// counts them — "Skipped ךָ — its "kh" and "aw" weren't heard."
function skippedNote(m, tradition) {
  const sounds = [m.consonant && consonantSay(m.consonant), m.vowel && vowelSay(m, tradition)].filter(Boolean)
  const said = sounds.map(x => `"${x}"`).join(' and ')
  const note = `Skipped ${m.display} — its ${said} ${sounds.length > 1 ? "weren't" : "wasn't"} heard.`
  return { note, problems: [{ kind: 'missing-sound', count: sounds.length, text: note }] }
}

// "The vowel is chirik: "ee" as in "see" — you said "oh" as in "go"."
function vowelNote(m, tradition) {
  const heard = describeHeardVowel(m.heardVowel)
  const expected = `The vowel is ${vowelSignName(m)}: ${describe(vowelSay(m, tradition))}`
  return heard ? `${expected} — you said ${heard}.` : `${expected} — it was left out.`
}

// A word that starts with ב, כ, פ or ת printed without a dot has lost its
// dagesh because the word before ends in a vowel and runs into it (צַוְּארֵי
// בִנְיָמִן, וַיְהִי־כֵן). Readers often say the hard sound they know from the
// word on its own ("Binyamin", "ken"); that's still a mistake, so the note
// explains why the letter is soft here.
const HARD_SOUND = { 'ב': 'b', 'כ': 'k', 'פ': 'p', 'ת': 't' }
const softAfterVowel = (atom, heardConsonant) =>
  atom.wordStart && !atom.dagesh && HARD_SOUND[atom.letter] === heardConsonant
const SOFT_AFTER_VOWEL_TIP = 'Tip: this word has no dot here because the word before it ends in a vowel and runs into it, so the letter is soft — read it as printed, even if you know the word with a hard sound.'

// A wrong letter: the letter (with the marks that decide its sound), its sound,
// what was said instead, and — when that's another letter's sound — which
// letter: "בּ (bet, with a dot) is "b" as in "boy" — you said "v" as in
// "very", the sound of ב (vet, no dot)." A wrong vowel in the same syllable
// is named after it.
function buildMismatchNote(m, tradition) {
  const L = m.atom.letter
  const expected = consonantSay(m.consonant)
  const heard = latinToSay(m.heardConsonant ?? '')

  let note
  let kind
  if (L === 'ה' && expected === 'h' && !heard) {
    kind = 'missing-sound'
    // Only a word-final ה with a dot is a mappiq; elsewhere (וֶהְיֵה) it's just a sounded ה
    note = m.atom.isFinal && m.atom.dagesh
      ? `ה with a dot (mappiq) is said "h" — it wasn't heard.`
      : `ה is said "h" here — it wasn't heard.`
  } else if (!expected && !heard) {
    // A letter with no consonant sound (shuruk וּ, alef): only its vowel is wrong
    if (!m.insertedBefore) return issue(vowelIssue(m.heardVowel), vowelNote(m, tradition))
    kind = 'extra-sound'
    note = `Extra "${latinToSay(m.insertedBefore)}" sound before ${m.display} — it shouldn't be there.`
  } else if (!expected && heard) {
    kind = 'extra-sound'
    note = `${L} is silent here — you said ${describe(heard)}.`
  } else if (!heard) {
    // Nothing heard at all: the whole syllable was left out
    if (m.vowel && !m.vowelMatched && !m.heardVowel) return skippedNote(m, tradition)
    kind = 'missing-sound'
    note = m.vowel && m.vowelMatched
      ? `The "${expected}" of ${m.display} wasn't heard — only its vowel, ${describe(vowelSay(m, tradition))}.`
      : `The "${expected}" of ${m.display} wasn't heard.`
  } else {
    kind = 'wrong-letter'
    const other = soundOfOtherLetter(m.atom, heard, tradition)
    note = `${letterLabel(m.atom, tradition)} is ${describe(expected)} — you said ${describe(heard)}` +
      (other ? `, the sound of ${other}.` : '.') +
      (softAfterVowel(m.atom, m.heardConsonant) ? ` ${SOFT_AFTER_VOWEL_TIP}` : '')
  }
  if (!m.vowel || m.vowelMatched) return issue(kind, note)
  const vowel = vowelNote(m, tradition)
  return {
    note: `${note} ${vowel}`,
    problems: [{ kind, count: 1, text: note }, { kind: vowelIssue(m.heardVowel), count: 1, text: vowel }],
  }
}

// Per-syllable sound breakdown for the sound-by-sound report. Each sound (the
// consonant letter and the vowel) is tagged correct/incorrect from the
// alignment. Silent letters — alef/ayin, final silent ה — produce an empty
// Latin sound and are omitted, since they contribute no sound to count. A
// sheva nach is silent too, but when shevas are graded (shevaType is set) it
// counts as its own sound, separate from sheva na: keeping it silent is
// what's graded. `seg` is a syllable object carrying { consonant, vowel, atom }.
// `say` is the sound in the sound key's spelling ("ee", "kh"; see soundGuide.js).
function makeBreakdown(seg, consonantCorrect, vowelCorrect, tradition) {
  const isNach = seg.shevaType === 'nach'
  return {
    consonant: seg.consonant
      ? { letter: seg.atom.letter, sound: seg.consonant, say: consonantSay(seg.consonant), correct: consonantCorrect }
      : null,
    vowel: seg.vowel || isNach
      ? { name: breakdownVowelName(seg), sound: isNach ? '' : seg.vowel, say: vowelSay(seg, tradition) ?? '', correct: vowelCorrect }
      : null,
  }
}

// The vowel's row in the sound-by-sound report. Hataf patach is the same "a"
// as patach, so it shares patach's row. A sheva that may be either is graded
// as vocal (it shows "e"), so it counts as sheva na.
function breakdownVowelName(seg) {
  const v = seg.atom.vowel
  if (v === 'sheva') return seg.shevaType === 'nach' ? 'sheva-nach' : 'sheva-na'
  if (v === 'hataf-patah') return 'patah'
  if (seg.qamatsType === 'katan') return 'qamats-katan'
  return v
}

// ── Public API ───────────────────────────────────────────────────────

// Score a single word: returns { word, score, errorType, phoneticHeard,
// expectedPhonetic, syllables: [{ phoneme, note, problems, breakdown }] }. A syllable
// is right when it has no note and all its sounds are right (syllableRight).
export function scoreWordAgainstTranscription(referenceWord, heardPhonetic, settings = {}) {
  const { tradition = 'sephardic', shevaMode = 'enforce' } = settings
  const atoms = tokenizeWord(referenceWord)
  const { segments, fullPhonetic } = getExpectedPhonetic(atoms, { tradition, shevaMode })
  const syllables = buildSyllables(atoms, segments)

  // No letters to grade (e.g. a stray punctuation token) — nothing to score
  if (syllables.length === 0) {
    return {
      word: referenceWord, score: 100, errorType: 'None',
      phoneticHeard: heardPhonetic ?? '', expectedPhonetic: '', syllables: [],
    }
  }

  // Omission: no heard phonetic at all
  if (!heardPhonetic || normalizeStudent(heardPhonetic).length === 0) {
    return {
      word: referenceWord,
      score: 0,
      errorType: 'Omission',
      phoneticHeard: '',
      expectedPhonetic: fullPhonetic,
      syllables: syllables.map(s => ({
        phoneme: s.display,
        note: '',
        problems: [],
        breakdown: makeBreakdown(s, false, false, tradition),
      })),
    }
  }

  const { matches, trailing } = alignSyllables(syllables, heardPhonetic)

  const scoredSyllables = matches.map(m => ({
    phoneme: m.display,
    ...syllableNote(m, tradition, shevaMode),
    breakdown: makeBreakdown(m, !!m.consonantMatched, !!m.vowelMatched, tradition),
    _match: m,
  }))

  // Penalize any trailing chars the student said after the word's expected end.
  // Attach the note to the last audible syllable so it's visible in the panel.
  if (trailing) {
    for (let i = scoredSyllables.length - 1; i >= 0; i--) {
      if (scoredSyllables[i]._match.expected) {
        const ex = scoredSyllables[i]
        const trailingNote = `Extra "${latinToSay(trailing)}" sound at the end of the word — it shouldn't be there.`
        scoredSyllables[i] = {
          ...ex,
          note: ex.note ? `${ex.note} ${trailingNote}` : trailingNote,
          problems: [...ex.problems, { kind: 'extra-sound', count: 1, text: trailingNote }],
        }
        break
      }
    }
  }

  // Strip the internal _match field before returning
  const graded = scoredSyllables.map(({ _match, ...rest }) => rest)
  const errorType = graded.every(syllableRight) ? 'None' : 'Mispronunciation'
  return {
    word: referenceWord,
    score: wordScoreOf({ errorType, phonemes: graded }).score,
    errorType,
    phoneticHeard: heardPhonetic,
    expectedPhonetic: fullPhonetic,
    syllables: graded,
  }
}

// Split what was heard for a run of maqef-joined words (אֶל־, אַבְרָם heard
// together as "elavram") into each word's part. The run is aligned as one
// phrase, so sounds that run across the maqef land where they belong
// (אֶת־שָׂרַי "etsaray": the "t" is ת, the "s" is שׂ), then cut where each
// word's first letter was heard. Returns one string per word ('' for a word
// that wasn't heard).
export function splitHeardAcrossWords(words, heard, settings = {}) {
  const { tradition = 'sephardic', shevaMode = 'enforce' } = settings
  const atoms = tokenizeWord(words.join(''))
  const { segments } = getExpectedPhonetic(atoms, { tradition, shevaMode })
  const { matches } = alignSyllables(buildSyllables(atoms, segments), heard)
  const student = normalizeStudent(heard).replace(/\s+/g, '')
  const starts = matches.filter(m => m.atom.wordStart).map(m => m.heardAt)
  starts[0] = 0
  return words.map((_, k) => student.slice(starts[k] ?? student.length, starts[k + 1] ?? student.length))
}

// Score an entire utterance: word-by-word using provided per-word transcriptions.
export function scoreWords(referenceWords, perWordHeard, settings = {}) {
  return referenceWords.map((word, i) => scoreWordAgainstTranscription(word, perWordHeard[i] ?? '', settings))
}
